import{_ as o,o as t,c as d,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"BrandHub — System Technical Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/technical-overview.md","filePath":"architecture/technical-overview.md"}'),a={name:"architecture/technical-overview.md"};function r(i,e,s,n,l,u){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="brandhub-—-system-technical-overview" tabindex="-1">BrandHub — System Technical Overview <a class="header-anchor" href="#brandhub-—-system-technical-overview" aria-label="Permalink to &quot;BrandHub — System Technical Overview&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← Architecture Index</a> · <a href="./../adr/README.html">ADR Index</a> · <a href="./../api/README.html">API Contracts</a> · <a href="./../database/README.html">Database Hub</a></p><p>Master technical blueprint of the <strong>BrandHub</strong> platform, verified directly against the production codebase across all 7 repositories and aligned with the canonical hierarchy: <code>Agency / Personal Studio → Workspace → Media Package → Media Campaign → Task → Post</code>.</p><hr><h2 id="_1-platform-scope-canonical-domain-baseline" tabindex="-1">1. Platform Scope &amp; Canonical Domain Baseline <a class="header-anchor" href="#_1-platform-scope-canonical-domain-baseline" aria-label="Permalink to &quot;1. Platform Scope &amp; Canonical Domain Baseline&quot;">​</a></h2><ul><li><strong>Product Lines &amp; Subscription Catalog (6 Active Plans)</strong>: <ul><li><strong>Personal Studio (<code>agencies.company_type = &#39;PERSONAL&#39;</code>, 1-user <code>Owner</code> cap)</strong>: <code>STUDIO_FREE</code>, <code>STUDIO_PLUS</code>, <code>STUDIO_PRO</code>.</li><li><strong>Agency (<code>agencies.company_type = &#39;AGENCY&#39;</code>)</strong>: <code>BASIC</code> (Free), <code>PLUS</code> (<code>990,000 VND/month</code> with 3/6/12-month cycle discounts), and <code>ENTERPRISE</code> (<code>3,990,000 VND/month</code>, <code>500 GB</code> storage).</li></ul></li><li><strong>6 Canonical System Roles</strong>: <code>Guest</code>, <code>Owner</code> (fixed per company via <code>agencies.owner_id</code>), <code>Manager</code>, <code>Creator</code>, <code>Client</code> (assigned per workspace in <code>workspace_members</code>), and <code>Admin</code> (platform-wide governance via <code>user_system_roles</code>).</li><li><strong>Functional Scope</strong>: <strong>141 Atomic Functional Requirements (<code>3.2.1</code>–<code>3.10.14</code>)</strong> mapped 1-to-1 with <strong>141 Use Cases (<code>UC-001</code>–<code>UC-141</code>)</strong> across <strong>9 functional domains</strong> (<a href="./../ba/README.html">BA Master Index</a>, <a href="./../ba/use-cases/README.html">Use Case Catalog</a>).</li><li><strong>4 Supported Social Publishing Platforms</strong>: Strictly <strong>Facebook</strong>, <strong>Instagram</strong>, <strong>TikTok</strong>, and <strong>Threads</strong>.</li><li><strong>Payment Gateway</strong>: <strong>SePay (VietQR)</strong> (<code>SEEPAY</code>) for upgrade-only plan orders (<code>FR 3.9.1</code>–<code>3.9.2</code>), storage add-ons, and AI credit top-ups.</li></ul><hr><h2 id="_2-polyrepo-runtime-stack-real-codebase-versions" tabindex="-1">2. Polyrepo Runtime Stack (Real Codebase Versions) <a class="header-anchor" href="#_2-polyrepo-runtime-stack-real-codebase-versions" aria-label="Permalink to &quot;2. Polyrepo Runtime Stack (Real Codebase Versions)&quot;">​</a></h2><p>Governed by <a href="./../adr/adr-001-polyrepo.html">ADR-001</a> and visualized in <a href="/brandhub-infrastructure/view.html?file=architecture/polyrepo-structure.html">Polyrepo Structure</a>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Repository</th><th style="text-align:left;">Language &amp; Framework Versions</th><th style="text-align:left;">Key Internal Modules / Libraries</th><th style="text-align:left;">Runtime Target</th></tr></thead><tbody><tr><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;">Java 21, Spring Cloud Gateway (WebFlux / Netty), Reactive Redis</td><td style="text-align:left;"><code>RequestIdWebFilter</code>, <code>InboundSecurityWebFilter</code>, <code>JwtAuthFilterGatewayFilterFactory</code>, <code>RateLimitGatewayFilterFactory</code>, <code>LoggingGlobalFilter</code>, <code>GlobalErrorWebExceptionHandler</code></td><td style="text-align:left;"><code>:8080</code> (<code>gateway</code> EC2 <code>172.31.27.199</code> behind Nginx <code>:443</code>)</td></tr><tr><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;">Java 21, Spring Boot 3, Spring Security, JPA + JDBC, Spring Data MongoDB, Spring WebSocket STOMP, AWS Encryption SDK</td><td style="text-align:left;"><code>122</code> REST/STOMP controllers across <code>auth</code>, <code>user</code>, <code>agency</code>, <code>workspace</code>, <code>client</code>, <code>media</code>, <code>task</code>, <code>content</code>, <code>material</code>, <code>social</code>, <code>chat</code>, <code>survey</code>, <code>mail</code>, <code>video</code>, <code>ai</code>, <code>trend</code>, <code>collaborator</code>, <code>billing</code>, <code>analytics</code>, <code>monitoring</code>, <code>admin</code></td><td style="text-align:left;"><code>:8081</code> (<code>core</code> EC2 <code>172.31.24.149</code>)</td></tr><tr><td style="text-align:left;"><code>brandhub-ai-service</code></td><td style="text-align:left;">Python 3.11+, FastAPI, ChromaDB <code>1.5.9</code>, Neo4j Async Driver, SentenceTransformers, PhoBERT</td><td style="text-align:left;"><code>15</code> v1 routers + v2 commercial image + internal routers; <code>caption_service</code>, <code>ltx_director</code>, <code>qwen_ambassador_client</code>, <code>product_video</code>, <code>server_video_edit</code>, <code>trend_fit</code>, <code>CrawlBatchConsumer</code></td><td style="text-align:left;"><code>:8082</code> (<code>ai</code> EC2 <code>172.31.20.60</code>)</td></tr><tr><td style="text-align:left;"><code>brandhub-publisher-service</code></td><td style="text-align:left;">Java 21, Spring Boot 3, Spring AMQP, StringRedisTemplate</td><td style="text-align:left;"><code>PublishJobConsumer</code> (<code>processingPostIds:{postId}:{platform}</code> lock), <code>SocialOAuthController</code>, <code>TokenRefreshScheduler</code>, <code>FacebookPublishAdapter</code>, <code>InstagramPublishAdapter</code>, <code>TikTokPublishAdapter</code>, <code>ThreadsPublishAdapter</code></td><td style="text-align:left;"><code>:8083</code> (<code>core</code> EC2 <code>172.31.24.149</code>)</td></tr><tr><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;">TypeScript <code>6.0</code>, React <code>19.2.6</code>, Vite <code>8.3.8</code>, Tailwind CSS <code>4.3.0</code></td><td style="text-align:left;">TanStack Query <code>5.100</code>, Zustand <code>5.0</code>, Radix UI / Shadcn <code>4.13</code>, TipTap <code>3.35</code> + Yjs <code>13.6</code> CRDT, <code>@stomp/stompjs</code> <code>7.3</code>, Agora RTC <code>4.24.9</code>, FullCalendar <code>6.1</code>, Recharts <code>3.10</code>, <code>i18next</code> (<code>vi</code>/<code>en</code>)</td><td style="text-align:left;"><code>:3000</code> local / S3 + CloudFront (<code>brandhub.id.vn</code>)</td></tr><tr><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;">TypeScript <code>6.0</code>, Expo SDK <code>58.0.26</code>, React Native <code>0.88.1</code>, React <code>19.3.0</code></td><td style="text-align:left;">React Navigation <code>7</code>, TanStack Query <code>5.100</code>, Zustand <code>5.0</code>, <code>@stomp/stompjs</code> <code>7.5</code>, Yjs <code>13.6</code>, Vision Camera <code>5.2</code>, <code>expo-secure-store</code>, <code>expo-local-authentication</code>, <code>expo-notifications</code></td><td style="text-align:left;">Metro <code>:8090</code> local / Android &amp; iOS</td></tr><tr><td style="text-align:left;"><code>brandhub-infrastructure</code></td><td style="text-align:left;">Terraform <code>~&gt; 6.0</code> (AWS Provider <code>6.70</code>), Docker Compose v2, Python 3.12, VitePress</td><td style="text-align:left;"><code>database/</code> (<code>init/</code>, <code>migrations/</code>), <code>docker/</code>, <code>prod/</code> (<code>hosts/</code>, <code>terraform/</code>, <code>loadtest/</code>), <code>gpu-workers/wan-vace/</code>, <code>scripts/</code>, <code>docs/</code></td><td style="text-align:left;">AWS <code>134875421878</code>, Vast.ai GPU, GitHub Pages</td></tr></tbody></table><hr><h2 id="_3-polyglot-persistence-real-time-data-plane" tabindex="-1">3. Polyglot Persistence &amp; Real-Time Data Plane <a class="header-anchor" href="#_3-polyglot-persistence-real-time-data-plane" aria-label="Permalink to &quot;3. Polyglot Persistence &amp; Real-Time Data Plane&quot;">​</a></h2><p>Governed by <a href="./../adr/adr-002-database-split.html">ADR-002</a> and detailed in <a href="./../database/README.html">Database Hub</a> &amp; <a href="./../database/schema/erd-entity-descriptions.html">ERD Entity Descriptions</a>:</p><ol><li><strong>PostgreSQL 17 (<code>97</code> tables in <code>database/init/init-postgres-v2.sql</code>)</strong>: Solely owned by <code>brandhub-business-service</code> (<code>33</code> JPA <code>@Entity</code> classes + <code>64</code> SQL/JDBC tables). Stores identity, 2-tier RBAC, Media Packages &amp; Campaigns, SePay billing orders/cycles/audit logs, double-entry AI credit wallets &amp; reservations, <code>product_video_*</code> coordinator state, S3/Drive/Client Vault storage quotas, mail batches, and <code>user_notifications</code> (emitting PostgreSQL <code>NOTIFY user_notification</code> on commit).</li><li><strong>MongoDB 7.0 (<code>52</code> collections in <code>database/init/init-mongo.js</code>, MongoDB Atlas in prod)</strong>: Stores <code>tasks</code>, <code>task_approvals</code>, <code>task_sections</code> (<code>DA-1274</code> role sections), <code>posts</code>, <code>content_requests</code>, <code>materials</code>/<code>material_folders</code>/<code>material_versions</code>/<code>client_vault_shares</code>, <code>chat_*</code> (<code>8</code> collections including Agora calls &amp; scheduled messages), <code>video_*</code> (<code>4</code> collections), <code>surveys</code>/<code>survey_responses</code>, <code>mail_templates</code>, <code>social_accounts</code>, <code>monitoring_*</code>, <code>knowledge_documents</code>, <code>ai_usage_logs</code>, and <code>publish_logs</code>.</li><li><strong>Redis 7.2 (<code>redis:7.2-alpine</code>, AOF)</strong>: Stores <code>jwt:blacklist:{jti}</code> (<code>15m</code>), <code>ratelimit:gateway:{userId}:{minute}</code> (<code>60s</code>), <code>oauth:state:{state}</code> (<code>10m</code>), publisher locks <code>processingPostIds:{postId}:{platform}</code> (<code>30m</code>), and Vietnam trend rankings <code>trends:vn:{date}:{category}</code> (<code>6h</code>) (<a href="./../database/redis-cache/redis-key-patterns.html">Redis Key Patterns</a>).</li><li><strong>ChromaDB 1.5.9 (<code>384d</code> HNSW)</strong> &amp; <strong>Neo4j 5.26 / Aura</strong>: Owned by <code>brandhub-ai-service</code> for tenant-isolated Brand Guideline RAG (<code>intfloat/multilingual-e5-small</code>) and Trend Knowledge Graph scoring (<a href="./../database/ai-vector/hybrid-db-schema.html">Hybrid DB Schema</a>).</li></ol><hr><h2 id="_4-inter-service-communication-security-architecture" tabindex="-1">4. Inter-Service Communication &amp; Security Architecture <a class="header-anchor" href="#_4-inter-service-communication-security-architecture" aria-label="Permalink to &quot;4. Inter-Service Communication &amp; Security Architecture&quot;">​</a></h2><ul><li><strong>Perimeter Ingress &amp; RS256 Auth (<a href="./../adr/adr-004-spring-cloud-gateway.html">ADR-004</a>, <a href="./../api/rs256-jwt-flow.html">RS256 JWT Flow</a>)</strong>: <code>InboundSecurityWebFilter</code> strips spoofable <code>X-User-*</code> and <code>X-Internal-Key</code> headers at the edge; <code>JwtAuthFilterGatewayFilterFactory</code> verifies RS256 signatures using <code>JWT_PUBLIC_KEY</code> and checks Redis <code>jwt:blacklist:{jti}</code>; <code>brandhub-business-service</code> independently re-verifies the Bearer token and evaluates live PostgreSQL roles (<a href="./../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a>).</li><li><strong>Real-Time STOMP WebSockets (<code>WebSocketConfig.java</code>)</strong>: <ul><li><code>/ws/tasks</code>: Handshake-authenticated Yjs CRDT collaborative content sync (<code>/app/tasks/{taskId}/content</code> → persisted in <code>task_content_operations</code> → broadcast to <code>/topic/tasks/{taskId}/content</code>) plus ephemeral cursor awareness (<code>/topic/tasks/{taskId}/awareness</code>).</li><li><code>/ws/chat</code>: Workspace channel messaging, reactions, read receipts, call signaling, and real-time in-app inbox pushes (<code>/user/queue/notifications</code> driven by PostgreSQL <code>LISTEN user_notification</code>).</li></ul></li><li><strong>Internal AI Orchestration (<a href="./business-ai-rest-contract.html">Business–AI REST Contract</a>)</strong>: <code>business-service</code> reserves credits in <code>ai_credit_reservations</code>, calls <code>ai-service</code> (<code>:8082</code>) with <code>X-Internal-Key</code>, and settles or refunds credits atomically upon completion.</li><li><strong>Asynchronous Social Publishing (<a href="./../adr/adr-003-rabbitmq.html">ADR-003</a>, <a href="/brandhub-infrastructure/view.html?file=architecture/rabbitmq-publisher-contract.html">RabbitMQ Contract</a>)</strong>: <code>business-service</code> publishes <code>PublishJobMessage</code> to <code>publisher.job.exchange</code> (<code>publisher.job.queue</code>); <code>publisher-service</code> executes platform adapters with <code>1m</code>/<code>5m</code>/<code>15m</code> TTL retry queues and <code>publisher.job.dlq</code>.</li><li><strong>Cryptographic Storage Controls</strong>: Social OAuth tokens use <code>AES-256-GCM</code> (<code>CryptoUtils</code>), while private Workspace Repository and <code>Client</code> Vault S3 payloads (<code>repository/*</code>, <code>client-vault/*</code>) are pre-encrypted before S3 upload using AWS Encryption SDK <code>ALG_AES_256_GCM_HKDF_SHA512_COMMIT_KEY</code> (<code>RepositoryEnvelopeCrypto</code>).</li></ul><hr><h2 id="_5-cloud-production-aws-ap-southeast-1-on-demand-gpu-topology" tabindex="-1">5. Cloud Production (<code>AWS ap-southeast-1</code>) &amp; On-Demand GPU Topology <a class="header-anchor" href="#_5-cloud-production-aws-ap-southeast-1-on-demand-gpu-topology" aria-label="Permalink to &quot;5. Cloud Production (`AWS ap-southeast-1`) &amp; On-Demand GPU Topology&quot;">​</a></h2><ul><li><strong>Frontend Edge (<code>02-frontend</code>)</strong>: Private S3 (<code>brandhub-web-prd-134875421878</code>) + CloudFront OAC + <code>brandhub-public-routes</code> viewer function (<code>brandhub.id.vn</code>).</li><li><strong>5-Host Backend Fleet (<code>03-backend</code>)</strong>: <code>gateway</code> (<code>172.31.27.199</code>, <code>t3.small</code>), <code>core</code> (<code>172.31.24.149</code>, <code>m7i-flex.large</code>, including nightly <code>db-backup</code> to <code>s3://brandhub-db-backup-prd-134875421878</code>), <code>ai</code> (<code>172.31.20.60</code>, <code>c7i-flex.large</code>), wakeable <code>crawl</code> (<code>172.31.20.50</code>, <code>c7i-flex.large</code> behind <code>crawl-gate</code> <code>:8084</code>), and wakeable <code>edit-video</code> (<code>172.31.20.80</code>, <code>m7i-flex.large</code> behind Nginx <code>/edit-video/</code>) — see <a href="./../operations/deployment-acct134.html">Deployment Runbook</a> and <a href="./../operations/wake-on-request.html">Wake-on-Request Architecture</a>.</li><li><strong>External Vast.ai GPU Workers (<code>gpu-workers/wan-vace/</code>)</strong>: Runs <strong>ComfyUI + Wan 2.2 Fun VACE 14B + Wan 2.2 S2V 14B + Qwen Image 2.1</strong> (<code>&gt;= 48 GB VRAM</code>) behind <code>X-API-Key</code> FastAPI (<code>vace_api.py</code> <code>:10200</code>) for 15–20s multi-segment product videos, virtual brand ambassadors, and commercial product photography.</li></ul>',20)])])}const g=o(a,[["render",r]]);export{h as __pageData,g as default};
